<?php require __DIR__.'/_head.php';$today=$pdo->query("SELECT COUNT(*) c,COALESCE(SUM(total),0) s FROM orders WHERE DATE(created_at)=CURDATE()")->fetch();$month=$pdo->query("SELECT COUNT(*) c,COALESCE(SUM(total),0) s FROM orders WHERE YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE())")->fetch();?>
<h2>বিক্রির রিপোর্ট</h2><div class="stats"><div class="stat">আজকের অর্ডার<strong><?=$today['c']?></strong></div><div class="stat">আজকের অর্ডার টোটাল<strong><?=money($today['s'])?></strong></div><div class="stat">এই মাসের অর্ডার<strong><?=$month['c']?></strong></div><div class="stat">এই মাসের অর্ডার টোটাল<strong><?=money($month['s'])?></strong></div></div><p class="muted">দ্রষ্টব্য: যেসব পণ্যের দাম এখনো নির্ধারিত নয়, সেগুলোর বিক্রয়মূল্য অ্যাডমিন নিশ্চিত না করা পর্যন্ত রিপোর্টে অন্তর্ভুক্ত হবে না।</p><?php require __DIR__.'/_foot.php';?>
